import{z as i,x as d,o as E,c as A,q as o,j as t,D as e,d as s,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"线性类型与所有权","description":"","frontmatter":{"title":"线性类型与所有权","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linear-ownership.md","filePath":"cs/linear-ownership.md","lastUpdated":1791063341000}'),B={name:"cs/linear-ownership.md"};function p(c,a,m,h,_,u){const r=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=o('<h1 id="线性类型与所有权" tabindex="-1">线性类型与所有权 <a class="header-anchor" href="#线性类型与所有权" aria-label="Permalink to &quot;线性类型与所有权&quot;">​</a></h1><div class="epigraph"><p>线性假设：资源必须用恰好一次。所有权是把这条纪律编进类型，使别名与释放可静态拒绝，而不把每一次 `free` 交给程序员运气。</p><footer>—— 据 Girard, Linear Logic, 1987；Wadler, Linear Types Can Change the World, 1990；Reynolds, Syntactic Control of Interference 整理</footer></div><p>上一课<a href="/cs/dependent-types-intuition">依值类型</a>让类型依赖值。缺口是另一轴：<strong>用几次</strong>。STLC 的变量可自由复制；文件句柄、堆块、互斥锁不行。线性类型：\\(\\Gamma\\) 在应用时拆分，不能把同一线性变量传两次。Rust 的所有权是这条纪律的工程化（移动语义、一次析构）。本课钉规则直觉，不写借用——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HM 不管别名：两个 <code>ref</code> 可指同一单元，值限制只防多态。线性：项 \\(x\\) 的类型若线性，则 \\(x\\) 在体中恰好出现一次（或显式 <code>dup</code>/<code>drop</code> 能力）。缺口是<strong>上下文拆分</strong> \\(\\Gamma=\\Gamma_1+\\Gamma_2\\)，不是 Π。</p><p>所有权：值有唯一拥有者，移动转移拥有者，作用域结束析构。这是线性（或仿射：至多用一次）在表面语言的说法。仿射允许忽略；线性不允许泄漏未用资源。</p><h3 id="线性不是「引用计数等于-1」" tabindex="-1">线性不是「引用计数等于 1」 <a class="header-anchor" href="#线性不是「引用计数等于-1」" aria-label="Permalink to &quot;线性不是「引用计数等于 1」&quot;">​</a></h3><p>RC 是运行时；线性是静态。RC 可循环；线性类型通常禁止未跟踪的别名。不要把 ARC 当线性类型的定义。</p><p><span class="marginnote">Girard 线性逻辑。Wadler 1990。Baker、Reynolds 对干扰控制。Rust 把仿射+借用做成产品。本课不把线性逻辑的全部联结词当作业。</span></p><p><span class="marginnote">「线性」就是资源在类型层面必须恰好用一次的纪律；「仿射」放宽为至多用一次（允许丢弃）。直觉类比：电影票是线性的——检票用掉就没了，复制不出来；传单是仿射的——扔掉不看也不算错。Rust 的所有权属仿射一系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>核心规则：变量从 Γ 取出即删除；λ 的参数线性则体用一次。<code>!A</code>（指数）恢复任意复制。实现：编译器做消耗检查，失败则「use of moved value」。析构插入在移动路径的汇合，与 SSA 的 φ 类似——后课 SSA 再对照插入点。</p>',12)),(E(),t(l,null,{default:e(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OWN%5B%22%E5%94%AF%E4%B8%80%E6%8B%A5%E6%9C%89%E8%80%85%22%5D%20--%3E%20MOVE%5B%22%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20MOVE%20--%3E%20DROP%5B%22%E6%9E%90%E6%9E%84%22%5D%0A%20%20OWN%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%E4%BD%BF%E7%94%A8%E4%B8%80%E6%AC%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>与<a href="/cs/typeclass-dictionary">字典</a>：<code>Drop</code> 是析构的类型类；线性保证调用次数。</p><p><span class="marginnote">直觉类比：移动像「过户」而不是「复印」——<code>let b = a</code> 之后资源登记在 b 名下，a 手里只剩一张作废的旧房本，再用它就是「use of moved value」。想要两份？要么显式深拷贝，要么等下一课的借用。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>闭包捕获线性值会消耗环境，故闭包本身线性。共享需要下一课的借用或显式 <code>Rc</code>。不要在线性语言里默许隐式复制大数组还声称有所有权。</p><p>C++ 移动是库约定加右值引用，类型系统不完整跟踪；对照用，不当成已解决。</p><p><span class="marginnote">为什么重要：文件句柄忘了关、锁忘了放，是 C 系语言最常见的一类 bug。线性类型把「用了几次」的错误从运行时测试挪到编译期：函数签名写明参数是 move 还是借，遗漏的 close/unlock 直接编译不过。</span></p>',6)),(E(),t(l,null,{default:e(()=>[n(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E8%B0%83%E7%94%A8%20f(x)%20%E5%8F%82%E6%95%B0%E4%B8%BA%E7%BA%BF%E6%80%A7%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20SP%7B%22%E4%B8%8A%E4%B8%8B%E6%96%87%20%CE%93%20%E6%8B%86%E7%BB%99%E5%90%84%E4%BD%BF%E7%94%A8%E7%82%B9%22%7D%0A%20%20SP%20--%20%22x%20%E6%81%B0%E5%A5%BD%E7%94%A8%E4%B8%80%E6%AC%A1%22%20--%3E%20OK%5B%22%E6%8B%86%E5%88%86%E6%88%90%E7%AB%8B%20%E6%A3%80%E6%9F%A5%E9%80%9A%E8%BF%87%22%5D%0A%20%20SP%20--%20%22x%20%E5%87%BA%E7%8E%B0%E7%AC%AC%E4%BA%8C%E6%AC%A1%22%20--%3E%20ERR%5B%22%E6%8A%A5%20use%20of%20moved%20value%22%5D%0A%20%20SP%20--%20%22x%20%E4%B8%80%E6%AC%A1%E6%B2%A1%E7%94%A8%22%20--%3E%20AFF%7B%22%E8%AF%AD%E8%A8%80%E7%BA%BF%E6%80%A7%E8%BF%98%E6%98%AF%E4%BB%BF%E5%B0%84%EF%BC%9F%22%7D%0A%20%20AFF%20--%20%22%E7%BA%BF%E6%80%A7%22%20--%3E%20LEAK%5B%22%E6%8A%A5%E8%B5%84%E6%BA%90%E6%B3%84%E6%BC%8F%22%5D%0A%20%20AFF%20--%20%22%E4%BB%BF%E5%B0%84%22%20--%3E%20DROP%5B%22%E5%85%81%E8%AE%B8%20%E5%B9%B6%E5%9C%A8%E4%BD%9C%E7%94%A8%E5%9F%9F%E6%9C%AB%E6%8F%92%E5%85%A5%E6%9E%90%E6%9E%84%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写生命周期。后课默认：所有权/线性管唯一与析构。下一课借用检查：临时共享如何不破坏唯一。</p><p>也不把线性当 GC 的替代证明；GC 语言仍可加线性能力（Haskell 的线性类型扩展点名）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线性：上下文拆分，资源用一次；仿射允许丢弃。</li><li>所有权是移动+析构的表面纪律。</li><li>复制须显式能力，不是 HM 默认。</li><li>出处：Girard, 1987；Wadler, 1990；对照 Reynolds。</li></ul>',5))])}const F=i(B,[["render",p]]);export{C as __pageData,F as default};
